arguments.newString:
"""用户登录模块。"""

import hmac

USERS = {
    "alice": "password123",
    "bob": "secret456",
}


def login(username, password):
    """校验用户名与密码，成功返回 True，失败返回 False。

    修复密码校验逻辑：去除密码首尾空白后再比较，
    并使用恒定时间比较，避免时序攻击。
    """
    if username not in USERS:
        return False
    return hmac.compare_digest(USERS[username], password.strip())

